describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before', async () => {
    const summaries = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const listFor = jest.fn().mockResolvedValue(summaries);
    const store = {listFor} as unknown as import('../../types/sessionStore.js').SessionStore;
    const h = listHarness(store);

    await h.send({type: 'list_sessions', limit: 10, before: {sessionId: 's3', updatedAt: '2026-01-01T00:05:00.000Z'}});

    expect(listFor).toHaveBeenCalledWith('u1', {
      limit: 10,
      before: {sessionId: 's3', updatedAt: '2026-01-01T00:05:00.000Z'},
    });
    expect(h.sent).toEqual([
      {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's2',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 4,
          },
        ],
      },
    ]);
  });

  it('answers an empty session_list when the store has no listFor', async () => {
    const store = {} as unknown as import('../../types/sessionStore.js').SessionStore;
    const h = listHarness(store);

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'session_list', sessions: []}]);
  });

  it('answers SERVER_ERROR when listFor throws', async () => {
    const store = {
      listFor: jest.fn().mockRejectedValue(new Error('database offline')),
    } as unknown as import('../../types/sessionStore.js').SessionStore;
    const h = listHarness(store);

    await h.send({type: 'list_sessions'});

    expect(h.frames()).toEqual(['error SERVER_ERROR']);
  });
});

