it('rejects list_sessions with invalid limit or malformed before cursor', () => {
  const malformed = [
    validateMessage({type: 'list_sessions', limit: 'invalid'}),
    validateMessage({type: 'list_sessions', limit: -10}),
    validateMessage({type: 'list_sessions', limit: 2.5}),
    validateMessage({type: 'list_sessions', before: 42}),
    validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
    validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'x'.repeat(129)}}),
    validateMessage({type: 'list_sessions', before: {updatedAt: 'invalid-date', sessionId: 's1'}}),
    validateMessage({type: 'list_sessions', before: {sessionId: 's1'}}),
  ];

  expect(malformed.map(r => r.valid)).toEqual([false, false, false, false, false, false, false, false]);
});
